package de.corporate.lc.email.service;
import de.corporate.lc.document.domain.LcDocument;import de.corporate.lc.document.repository.LcDocumentRepository;import de.corporate.lc.email.api.*;import de.corporate.lc.email.domain.EmailDelivery;import de.corporate.lc.email.repository.EmailDeliveryRepository;import de.corporate.lc.lc.repository.LetterOfCreditRepository;import jakarta.mail.MessagingException;import jakarta.mail.internet.MimeMessage;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.ByteArrayResource;import org.springframework.mail.javamail.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.util.*;
@Service public class EmailService{private final JavaMailSender mail;private final LetterOfCreditRepository lcs;private final LcDocumentRepository documents;private final EmailDeliveryRepository deliveries;private final boolean enabled;private final String from;public EmailService(JavaMailSender mail,LetterOfCreditRepository lcs,LcDocumentRepository documents,EmailDeliveryRepository deliveries,@Value("${app.mail.enabled:false}")boolean enabled,@Value("${app.mail.from:}")String from){this.mail=mail;this.lcs=lcs;this.documents=documents;this.deliveries=deliveries;this.enabled=enabled;this.from=from;}public Map<String,Object> status(){return Map.of("enabled",enabled&&!from.isBlank(),"from",from);}@Transactional(readOnly=true)public List<EmailDeliveryView> history(UUID lcId){if(!lcs.existsById(lcId))throw new NoSuchElementException("LC-Akte nicht gefunden.");return deliveries.findByLetterOfCreditIdOrderBySentAtDesc(lcId).stream().map(EmailDeliveryView::from).toList();}
@Transactional public EmailDeliveryView send(UUID lcId,EmailSendRequest request,String username){var lc=lcs.findById(lcId).orElseThrow(()->new NoSuchElementException("LC-Akte nicht gefunden."));var delivery=new EmailDelivery();delivery.setLetterOfCredit(lc);delivery.setRecipients(String.join("\n",request.recipients()));delivery.setSubject(request.subject());delivery.setSentBy(username);List<LcDocument> attachments=loadAttachments(lcId,request.documentIds());delivery.setAttachmentNames(attachments.stream().map(LcDocument::getOriginalFilename).reduce((a,b)->a+"\n"+b).orElse(null));if(!enabled||from.isBlank()){delivery.setStatus("FAILED");delivery.setErrorMessage("SMTP-Versand ist noch nicht konfiguriert.");return EmailDeliveryView.from(deliveries.save(delivery));}try{MimeMessage message=mail.createMimeMessage();MimeMessageHelper helper=new MimeMessageHelper(message,true,StandardCharsets.UTF_8.name());helper.setFrom(from);helper.setTo(request.recipients().toArray(String[]::new));helper.setSubject(request.subject());helper.setText(request.body(),false);for(LcDocument document:attachments)helper.addAttachment(document.getOriginalFilename(),new ByteArrayResource(document.getContent()),document.getContentType());mail.send(message);delivery.setStatus("SENT");}catch(MessagingException|RuntimeException ex){delivery.setStatus("FAILED");String error=ex.getMessage()==null?"Unbekannter Versandfehler":ex.getMessage();delivery.setErrorMessage(error.substring(0,Math.min(1000,error.length())));}return EmailDeliveryView.from(deliveries.save(delivery));}
private List<LcDocument> loadAttachments(UUID lcId,List<UUID> ids){if(ids==null||ids.isEmpty())return List.of();List<UUID> unique=ids.stream().distinct().toList(),missing=new ArrayList<>(unique);List<LcDocument> result=documents.findAllById(unique);missing.removeAll(result.stream().map(LcDocument::getId).toList());if(!missing.isEmpty()||result.stream().anyMatch(d->!d.getLetterOfCredit().getId().equals(lcId)))throw new IllegalArgumentException("Mindestens ein Anhang gehört nicht zu dieser LC-Akte.");return result;}}
